package it.ekonex.voice.watch;
import android.content.Context; import android.os.Handler; import android.os.Looper; import android.util.Base64; import android.util.Log;
import com.google.firebase.messaging.FirebaseMessaging;
import java.net.HttpURLConnection; import java.net.URL; import java.nio.charset.StandardCharsets; import java.security.KeyStore;
import javax.crypto.Cipher; import javax.crypto.SecretKey; import javax.crypto.spec.GCMParameterSpec;
public final class FcmRegistration {
 private static final String TAG="EkonexWearFcm"; private static final long[] RETRY_MS={60000L,300000L,900000L}; private static int retry;
 private FcmRegistration(){}
 public static void sync(Context c){Context app=c.getApplicationContext();FirebaseMessaging messaging=FirebaseMessaging.getInstance();messaging.setAutoInitEnabled(true);messaging.getToken().addOnCompleteListener(task->{if(!task.isSuccessful()||task.getResult()==null||task.getResult().isEmpty()){Log.w(TAG,"FCM token unavailable",task.getException());schedule(app);return;}new Thread(()->send(app,task.getResult()),"ekonex-fcm-register").start();});}
 private static void schedule(Context c){int index=Math.min(retry++,RETRY_MS.length-1);new Handler(Looper.getMainLooper()).postDelayed(()->sync(c),RETRY_MS[index]);}
 private static void send(Context c,String token){try{String credential=credential(c);if(credential.isEmpty()){Log.w(TAG,"Wear credential unavailable");schedule(c);return;}HttpURLConnection x=(HttpURLConnection)new URL(BuildConfig.EKONEX_API_BASE+"/push-token").openConnection();try{x.setRequestMethod("PUT");x.setConnectTimeout(6000);x.setReadTimeout(12000);x.setRequestProperty("Authorization","Bearer "+credential);x.setRequestProperty("Content-Type","application/json");x.setDoOutput(true);String body="{\"token\":\""+token.replace("\\","\\\\").replace("\"","\\\"")+"\"}";x.getOutputStream().write(body.getBytes(StandardCharsets.UTF_8));int status=x.getResponseCode();if(status==204){retry=0;c.getSharedPreferences("ekonex_wear",Context.MODE_PRIVATE).edit().putString("fcm_token",token).apply();Log.i(TAG,"FCM token registered");}else{Log.w(TAG,"FCM registration HTTP "+status);schedule(c);}}finally{x.disconnect();}}catch(Exception error){Log.w(TAG,"FCM registration failed",error);schedule(c);}}
 private static String credential(Context c)throws Exception{String iv=c.getSharedPreferences("ekonex_wear",Context.MODE_PRIVATE).getString("iv","");String value=c.getSharedPreferences("ekonex_wear",Context.MODE_PRIVATE).getString("credential","");if(iv.isEmpty()||value.isEmpty())return"";KeyStore s=KeyStore.getInstance("AndroidKeyStore");s.load(null);SecretKey k=((KeyStore.SecretKeyEntry)s.getEntry("ekonex_wear_device_v1",null)).getSecretKey();Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,k,new GCMParameterSpec(128,Base64.decode(iv,Base64.NO_WRAP)));return new String(cipher.doFinal(Base64.decode(value,Base64.NO_WRAP)),StandardCharsets.UTF_8);}
}
